// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 機能マスタの全件一覧 (settings:admin)
	// (GET /admin/actions)
	ListActions(c *gin.Context)
	// 機能を変更 (settings:admin)
	// (PATCH /admin/actions/{id})
	UpdateAction(c *gin.Context, id ActionId)
	// ユーザー一覧と機能権限 (settings:admin)
	// (GET /admin/users)
	ListUsers(c *gin.Context, params ListUsersParams)
	// ユーザーの機能権限を一括置換 (settings:admin)
	// (PUT /admin/users/{objectGuid}/auth)
	SetUserAuth(c *gin.Context, objectGuid openapi_types.UUID)
	// LDAP(AD) 認証してセッション cookie を発行
	// (POST /auth/login)
	Login(c *gin.Context)
	// セッションを破棄する
	// (POST /auth/logout)
	Logout(c *gin.Context)
	// 現在のユーザーと機能権限を返す
	// (GET /auth/me)
	GetMe(c *gin.Context)
	// 接続の一覧 (settings:admin)
	// (GET /connections)
	ListConnections(c *gin.Context)
	// 接続を登録 (settings:admin)
	// (POST /connections)
	CreateConnection(c *gin.Context)
	// 保存前の疎通テスト (settings:admin)
	// (POST /connections/test)
	TestConnectionParams(c *gin.Context)
	// 接続を削除 (settings:admin)
	// (DELETE /connections/{id})
	DeleteConnection(c *gin.Context, id ConnectionId)
	// 接続を変更 (settings:admin)
	// (PATCH /connections/{id})
	UpdateConnection(c *gin.Context, id ConnectionId)
	// 保存済み接続の疎通テスト (settings:admin)
	// (POST /connections/{id}/test)
	TestConnection(c *gin.Context, id ConnectionId)
	// ダッシュボードテンプレートの一覧
	// (GET /dash-templates)
	ListDashTemplates(c *gin.Context, params ListDashTemplatesParams)
	// テンプレートを作成 (settings:admin)
	// (POST /dash-templates)
	CreateDashTemplate(c *gin.Context)
	// テンプレートを削除 (settings:admin)
	// (DELETE /dash-templates/{id})
	DeleteDashTemplate(c *gin.Context, id DashTemplateId)
	// テンプレート詳細(items 込み)
	// (GET /dash-templates/{id})
	GetDashTemplate(c *gin.Context, id DashTemplateId)
	// テンプレートを変更 (settings:admin)
	// (PATCH /dash-templates/{id})
	UpdateDashTemplate(c *gin.Context, id DashTemplateId)
	// テンプレート項目を一括置換 (settings:admin)
	// (PUT /dash-templates/{id}/items)
	SetDashTemplateItems(c *gin.Context, id DashTemplateId)
	// 操作履歴の検索 (history:maintainer+)
	// (GET /history)
	ListHistory(c *gin.Context, params ListHistoryParams)
	// 操作履歴を CSV でエクスポート (history:maintainer+)
	// (GET /history/export)
	ExportHistory(c *gin.Context, params ExportHistoryParams)
	// detail が 1MB を超えて退避された全文を取得 (history:maintainer+)
	// (GET /history/{id}/overflow)
	GetHistoryOverflow(c *gin.Context, id int)
	// 管理対象テーブルの一覧
	// (GET /managed-tables)
	ListManagedTables(c *gin.Context, params ListManagedTablesParams)
	// テーブルを管理対象として登録 (settings:admin)
	// (POST /managed-tables)
	CreateManagedTable(c *gin.Context)
	// 管理対象から外す (settings:admin)
	// (DELETE /managed-tables/{id})
	DeleteManagedTable(c *gin.Context, id ManagedTableId)
	// 管理対象テーブルの表示名などを変更 (settings:admin)
	// (PATCH /managed-tables/{id})
	UpdateManagedTable(c *gin.Context, id ManagedTableId)
	// テーブルの列定義(フロントの動的描画用)
	// (GET /managed-tables/{id}/meta)
	GetTableMeta(c *gin.Context, id ManagedTableId)
	// 行データの取得(ページネーション)
	// (GET /managed-tables/{id}/rows)
	ListRows(c *gin.Context, id ManagedTableId, params ListRowsParams)
	// 追加・更新・削除を1トランザクションで一括反映 (table-maint:maintainer+)
	// (POST /managed-tables/{id}/rows/batch)
	ApplyBatch(c *gin.Context, id ManagedTableId)
	// 行データを CSV でエクスポート (table-maint:user+)
	// (GET /managed-tables/{id}/rows/export)
	ExportRows(c *gin.Context, id ManagedTableId, params ExportRowsParams)
	// 自分のダッシュボード項目一覧(position 順)
	// (GET /me/dash-items)
	GetMyDashItems(c *gin.Context)
	// 自分のダッシュボード項目を全置換
	// (PUT /me/dash-items)
	SetMyDashItems(c *gin.Context)
	// 個人設定の取得
	// (GET /me/settings)
	GetMySettings(c *gin.Context)
	// 個人設定の変更
	// (PATCH /me/settings)
	UpdateMySettings(c *gin.Context)
	// 登録候補テーブルの一覧 (settings:admin)
	// (GET /schema/tables)
	ListSchemaTables(c *gin.Context, params ListSchemaTablesParams)
	// 登録前のカラムプレビュー (settings:admin)
	// (GET /schema/tables/{schema}/{table}/columns)
	PreviewSchemaTable(c *gin.Context, schema string, table string, params PreviewSchemaTableParams)
}

